/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    Common                                  locCommon;
    InventTransferLine                      locInventTransferLine;
    InventTransferTable                     locInventTransferTable;
    AVAItemSetInventTransferLineExplodeBOM  locClassInstance;
    Args                                    locArgs;

    if(     _args
        &&  _args.record()
        &&  _args.record().RecId    )
    {
        locCommon = _args.record();

        if(_args.record().TableId == tableNum(InventTransferLine))
        {
            locInventTransferLine = locCommon;
            locClassInstance = AVAItemSetInventTransferLineExplodeBOM::newFromArgs(_args);
            locClassInstance.init();
            locClassInstance.run();
        }

        if(_args.record().TableId == tableNum(InventTransferTable))
        {
            locInventTransferTable  = locCommon;

            InventTransferTable::avaItemSetExpandPossiblePositions(_args, locInventTransferTable.TransferId);

            /* moved to static method in InventTransferTable
            locArgs                 = new Args();
            while select locInventTransferLine
            where   locInventTransferLine.TransferId == locInventTransferTable.TransferId
                &&  locInventTransferLine.AVAItemSet
                &&  !locInventTransferLine.AVAItemSetExpanded
            {
                locArgs.caller(_args.caller());
                locArgs.record(locInventTransferLine);
                locClassInstance = AVAItemSetInventTransferLineExplodeBOM::newFromArgs(locArgs);
                //locClassInstance.init();
                locClassInstance.run();
            }
            */
        }
    }
}

