/// <summary>
///     AVA <c>init</c> method.
/// </summary>
/// <param name="_BOMBaseVersionNeeded">
///     <c>boolean</c> as type
/// </param>
public void init(boolean _BOMBaseVersionNeeded = true)
{
    Common  locCommon;

    if (baseArgs && baseArgs.record())
    {
        locCommon = baseArgs.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(InventTransferLine))
        {
            baseInventTransferLine  = locCommon;
            baseInventTransferTable = baseInventTransferLine.inventTransferTable();
            baseInventTransferId    = baseInventTransferLine.TransferId;
            baseItemId              = baseInventTransferLine.ItemId;
            baseInventTable         = InventTable::find(baseItemId);
            baseInventDim           = baseInventTransferLine.inventDim();

            if(_BOMBaseVersionNeeded)
            {
                this.initBaseBomVersion();
            }
        }
        else
        {
            baseInventTransferLine  = null;
            baseInventTransferTable = null;
            baseInventTransferId    = '';
            baseItemId              = '';
            baseInventTable         = null;
            baseInventDim           = null;
        }

    }
}

/// <summary>
///     AVA <c>run</c> method.
/// </summary>
public void run()
{
    if(baseBomVersion.RecId)
    {
        this.createItemSetLines();
    }
    else
    {
        throw error(error::wrongUseOfFunction(funcName()));
    }
}

/// <summary>
///     AVA <c>initBaseBomVersion</c> method.
/// </summary>
public void initBaseBomVersion()
{
    if(baseItemId)
    {
        baseBomVersion = BomVersion::findActive(baseItemId,
                                                DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                                baseInventTransferLine.QtyTransfer,
                                                baseInventTransferLine.inventDim()
                                                );

        if (    !baseBomVersion.Active
            ||  !baseBomVersion.Approved    )
        {
            warning(strFmt("@AVAItemSet:ItemSetBOMNotApprovedOrNotActive", baseItemId));
            throw error("@SYS21628");
        }
    }
}

/// <summary>
///     AVA <c>createItemSetLines</c> method.
/// </summary>
public void createItemSetLines()
{
    BOM locBOM;
    int bomlineCount;

    ttsBegin;
    while select locBOM
        where   locBOM.BOMId    == baseBomVersion.BOMId
            &&  locBOM.BOMType  == BOMType::Item
            &&  locBOM.BOMQty   > 0
    {
        bomlineCount++;
        this.createItemSetLine(locBOM, bomlineCount);
    }

    if (baseBomVersion)
    {
        this.updateBaseInventTransferLine();
    }
    ttscommit;
}

/// <summary>
///     AVA <c>createItemSetLine</c> method.
/// </summary>
/// <param name = "_bom">BOM</param>
/// <param name = "_lineCount">Int</param>
public void createItemSetLine(BOM _bom, int _lineCount)
{
    BOMCalcData         locBOMCalcData;
    real                locBOMFactor;


    locBOMFactor    = _bom.BOMQty / _bom.BOMQtySerie;

    locBOMCalcData  = this.initBOMCalcData(baseInventTransferLine);

    clsInventTransferLine.clear();

    clsInventTransferLine.initValue();
    clsInventTransferLine.initFromInventTransferTable(baseInventTransferTable, false);
    clsInventTransferLine.ItemId                    = _bom.ItemId;
    clsInventTransferLine.initFromInventTable(_bom.inventTable(), _bom.inventDimId);

    clsInventTransferLine.AVAItemSetSerie           = _bom.BOMQtySerie;
    clsInventTransferLine.AVAItemSetCompQtyPerSerie = _bom.BOMQty;
    clsInventTransferLine.LineNum                   = baseInventTransferLine.LineNum + 0.001 * _bom.LineNum;
    clsInventTransferLine.AVAItemSetParent          = baseInventTransferLine.InventTransId;
    clsInventTransferLine.AVAItemSetComponent       = NoYes::Yes;

    //values from ItemSet
    this.initComponentwithBaseInventTransferLine(_bom);

    clsInventTransferLine.AVAProdSchedDate          = baseInventTransferLine.AVAProdSchedDate;
    clsInventTransferLine.ShipDate                  = baseInventTransferLine.ShipDate;
    clsInventTransferLine.ReceiveDate               = baseInventTransferLine.ReceiveDate;
    clsInventTransferLine.DeliveryDateControlType   = baseInventTransferLine.DeliveryDateControlType;
    clsInventTransferLine.RemainStatus              = baseInventTransferLine.RemainStatus;

    clsInventTransferLine.write();
}

/// <summary>
///     AVA <c>initComponentwithBaseInventTransferLine</c> method.
/// </summary>
/// <param name="_bom">
///     <c>BOM</c> as type
/// </param>
public void initComponentwithBaseInventTransferLine(BOM _bom)
{
    clsInventTransferLine.QtyReceived               = baseInventTransferLine.QtyReceived            * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.QtyReceiveNow             = baseInventTransferLine.QtyReceiveNow          * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.QtyRemainReceive          = baseInventTransferLine.QtyRemainReceive       * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.QtyRemainShip             = baseInventTransferLine.QtyRemainShip          * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.QtyScrapped               = baseInventTransferLine.QtyScrapped            * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.QtyShipNow                = baseInventTransferLine.QtyShipNow             * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.QtyShipped                = baseInventTransferLine.QtyShipped             * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.QtyTransfer               = baseInventTransferLine.QtyTransfer            * _bom.BOMQty / _bom.BOMQtySerie;

    clsInventTransferLine.PdsCWQtyReceived          = baseInventTransferLine.PdsCWQtyReceived       * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.PdsCWQtyReceiveNow        = baseInventTransferLine.PdsCWQtyReceiveNow     * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.PdsCWQtyRemainReceive     = baseInventTransferLine.PdsCWQtyRemainReceive  * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.PdsCWQtyRemainShip        = baseInventTransferLine.PdsCWQtyRemainShip     * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.PdsCWQtyScrapped          = baseInventTransferLine.PdsCWQtyScrapped       * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.PdsCWQtyShipNow           = baseInventTransferLine.PdsCWQtyShipNow        * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.PdsCWQtyShipped           = baseInventTransferLine.PdsCWQtyShipped        * _bom.BOMQty / _bom.BOMQtySerie;
    clsInventTransferLine.PdsCWQtyTransfer          = baseInventTransferLine.PdsCWQtyTransfer       * _bom.BOMQty / _bom.BOMQtySerie;
}

/// <summary>
/// creates nwe BOMCalcData based on InventTransferLine
/// </summary>
/// <param name = "_inventTransferLine">InventTransferLine</param>
/// <returns>BOMCalcData</returns>
private BOMCalcData initBOMCalcData(InventTransferLine _inventTransferLine = baseInventTransferLine)
{
    BOMCalcData bomCalcData;

    bomCalcData = BOMCalcData::newInventTable(_inventTransferLine.QtyTransfer, baseInventTable);

    return bomCalcData;
}

/// <summary>
///     AVA <c>updateBaseInventTransferLine</c> method.
/// </summary>
public void updateBaseInventTransferLine()
{
    // deliver remainder
    /*
    baseInventTransferLine.QtyRemainShip = 0;
    if (baseInventTransferLine.validateWrite())
    {
        ttsbegin;
        baseInventTransferLine.selectForUpdate(true);
        baseInventTransferLine.updateDeliverRemainder();
        ttscommit;
    }
    */
    ttsbegin;
    // set to expanded and reduce qtys
    baseInventTransferLine.selectForUpdate(true);

    baseInventTransferLine.AVAItemSetExpanded = NoYes::Yes;

    baseInventTransferLine.QtyReceived              = 0;
    baseInventTransferLine.QtyReceiveNow            = 0;
    baseInventTransferLine.QtyRemainReceive         = 0;
    baseInventTransferLine.QtyRemainShip            = 0;
    baseInventTransferLine.QtyScrapped              = 0;
    baseInventTransferLine.QtyShipNow               = 0;
    baseInventTransferLine.QtyShipped               = 0;
    //baseInventTransferLine.QtyTransfer              = 0;

    baseInventTransferLine.PdsCWQtyReceived         = 0;
    baseInventTransferLine.PdsCWQtyReceiveNow       = 0;
    baseInventTransferLine.PdsCWQtyRemainReceive    = 0;
    baseInventTransferLine.PdsCWQtyRemainShip       = 0;
    baseInventTransferLine.PdsCWQtyScrapped         = 0;
    baseInventTransferLine.PdsCWQtyShipNow          = 0;
    baseInventTransferLine.PdsCWQtyShipped          = 0;
    //baseInventTransferLine.PdsCWQtyTransfer         = 0;

    baseInventTransferLine.update();

    //update remain with qty 0
    baseInventTransferLine.QtyRemainShip = 0.0;
    if (baseInventTransferLine.validateWrite())
    {
        baseInventTransferLine.updateDeliverRemainder();
    }
    ttscommit;
}

/// <summary>
///     AVA <c>updateItemSetComponents</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
boolean updateItemSetComponents()
{
    boolean retVal;

    if(     clsInventTransferLineNew.AVAItemSet
        &&  clsInventTransferLineNew.avaIsItemSetExpanded()  )
    {
        this.updateItemSetComponentscheckFieldIds();

        if(clsInventTransferLineChanged)
        {
            ttsbegin;

            while select forupdate clsInventTransferLine
            where   clsInventTransferLine.TransferId        == baseInventTransferId
                &&  clsInventTransferLine.AVAItemSetParent  == baseInventTransferLine.InventTransId
                &&  clsInventTransferLine.AVAItemSetComponent
            {
                this.updateItemSetComponentsUpdateFieldValue();
                clsInventTransferLine.update();
            }

            ttscommit;

            retVal = true;
        }
    }

    this.refreshCallerForm();

    return retVal;
}

/// <summary>
///     AVA <c>updateItemSetComponentsCheckFieldIds</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
boolean updateItemSetComponentsCheckFieldIds()
{
    boolean retVal;

    switch(clsInventTransferLineChangedFieldId)
    {
        case Fieldnum(SalesLine, InventDimId):
            clsInventTransferLineChanged    = true;
            break;

        case fieldNum(InventTransferLine, QtyTransfer):
            clsInventTransferLineChanged    = true;
            clsQtyTransferChanged           = true;
            break;

        case Fieldnum(InventTransferLine, AVAProdSchedDate):
            clsInventTransferLineChanged    = true;
            break;

        case Fieldnum(InventTransferLine, ShipDate):
            clsInventTransferLineChanged    = true;
            break;

        case Fieldnum(InventTransferLine, ReceiveDate):
            clsInventTransferLineChanged    = true;
            break;

        case Fieldnum(InventTransferLine, DeliveryDateControlType):
            clsInventTransferLineChanged    = true;
            break;

        case Fieldnum(InventTransferLine, RemainStatus):
            clsInventTransferLineChanged    = true;
            break;

        default:
            break;
    }

    retVal = clsInventTransferLineChanged;

    return retVal;
}

/// <summary>
///     AVA <c>updateItemSetComponentsUpdateFieldValue</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
boolean updateItemSetComponentsUpdateFieldValue()
{
    boolean     retVal;

    switch(clsInventTransferLineChangedFieldId)
    {
        case Fieldnum(InventTransferLine, InventDimId):
            clsInventTransferLine.InventDimId   = this.getComponentInventDimId();
            retVal = true;
            break;

        case fieldNum(InventTransferLine, AVAProdSchedDate):
            clsInventTransferLine.AVAProdSchedDate  = baseInventTransferLine.AVAProdSchedDate;
            if(     baseInventTransferLine.AVAProdSchedDate != dateNull()
                &&  baseInventTransferLine.AVAProdSchedDate > clsInventTransferLine.ShipDate   )
            {
                clsInventTransferLine.ShipDate       = baseInventTransferLine.AVAProdSchedDate;

                if(baseInventTransferLine.AVAProdSchedDate > clsInventTransferLine.ReceiveDate)
                {
                    clsInventTransferLine.ReceiveDate    = baseInventTransferLine.AVAProdSchedDate;
                }
            }
            retVal = true;
            break;

        case fieldNum(InventTransferLine, ShipDate):
            clsInventTransferLine.ShipDate      = baseInventTransferLine.ShipDate;
            clsInventTransferLine.ReceiveDate   = baseInventTransferLine.ReceiveDate;
            retVal = true;
            break;

        case fieldNum(InventTransferLine, ReceiveDate):
            clsInventTransferLine.ReceiveDate   = baseInventTransferLine.ReceiveDate;
            clsInventTransferLine.ShipDate      = baseInventTransferLine.ShipDate;
            retVal = true;
            break;

        case fieldNum(InventTransferLine, DeliveryDateControlType):
            clsInventTransferLine.DeliveryDateControlType = baseInventTransferLine.DeliveryDateControlType;
            retVal = true;
            break;

        case fieldNum(InventTransferLine, RemainStatus):
            clsInventTransferLine.RemainStatus = clsInventTransferLine.orig().RemainStatus;
            retVal = true;
            break;

        default:
            break;
    }
    if(     clsQtyTransferChanged
        &&  clsInventTransferLineChangedFieldId == fieldNum(InventTransferLine, QtyTransfer) )
    {
        if(clsInventTransferLineNew.QtyTransfer == 0)
        {
            clsInventTransferLine.QtyTransfer       = 0.0;
            clsInventTransferLine.QtyRemainReceive  = 0.0;
            clsInventTransferLine.QtyRemainShip     = 0.0;
        }
        else
        {
            clsInventTransferLine.QtyTransfer       = clsInventTransferLineNew.QtyTransfer      * clsInventTransferLine.AVAItemSetCompQtyPerSerie  / minOne(clsInventTransferLine.AVAItemSetSerie); // change from 0 to value so need to have the qty of serie as value
            //clsInventTransferLine.QtyRemainReceive  = clsInventTransferLineNew.QtyRemainReceive * clsInventTransferLine.AVAItemSetCompQtyPerSerie  / minOne(clsInventTransferLine.AVAItemSetSerie);
            //clsInventTransferLine.QtyRemainShip     = clsInventTransferLineNew.QtyRemainShip    * clsInventTransferLine.AVAItemSetCompQtyPerSerie  / minOne(clsInventTransferLine.AVAItemSetSerie);
            clsInventTransferLine.QtyRemainReceive       = clsInventTransferLine.QtyTransfer;
            clsInventTransferLine.QtyRemainShip          = clsInventTransferLine.QtyTransfer;
        }

        retVal = true;
    }

    return retVal;
}

/// <summary>
///     AVA <c>getComponentInventDimId</c> method.
/// </summary>
/// <returns>
///     <c>InventDimId</c> as return value
/// </returns>
public InventDimId getComponentInventDimId()
{
    InventDimId retVal;

    InventTable locInventTable;
    InventDim   locInventDimBase;
    InventDim   locInventDimNew;

    locInventTable                      = InventTable::find(clsInventTransferLine.ItemId);
    locInventDimBase                    = InventDim::find(baseInventTransferLine.InventDimId);
    locInventDimNew.InventSiteId        = locInventDimBase.InventSiteId;
    locInventDimNew.InventLocationId    = locInventDimBase.InventLocationId;
    locInventDimNew.ConfigId            = locInventTable.StandardConfigId;
    locInventDimNew                     = InventDim::findOrCreate(locInventDimNew);
    retVal                              = locInventDimNew.InventDimId;

    return retVal;
}

/// <summary>
///     AVA <c>getComponentInventDimId</c> method.
/// </summary>
public void refreshCallerForm()
{
    FormRun         locFormRunCaller;

    if(baseArgs)
    {
        locFormRunCaller    = baseArgs.caller();
        if (locFormRunCaller)
        {
            if(locFormRunCaller.name() == formStr(InventTransferOrders))
            {
                if (formHasMethod(locFormRunCaller, literalStr(avaRefreshInventTransferLineDS)))
                {
                    locFormRunCaller.avaRefreshInventTransferLineDS();
                }
            }
        }
    }
}
